/**
 * Envelope schema version. Stage 0 accepts 1 only; any other value is rejected rather than
 * best-effort parsed.
 */
export function validateEnvelopeSchemaVersion(value: unknown, path: string, out: SchemaViolation[]): void {
  checkInteger(value, path, out, { minimum: 1, maximum: 1 });
}

/**
 * Event payload. Its schema is selected by type. The event is bounded by
 * x-protocol.limits.max_review_event_bytes and each payload by its own x-max-bytes.
 */
export function validateEnvelopePayload(value: unknown, path: string, out: SchemaViolation[]): void {
  checkPlainObject(value, path, out);
}

/**
 * The docs/EVENTS.md section 2 event envelope. Every event names the organisation and
 * project it belongs to, its position in that project's stream, and the actor that caused
 * it; the payload schema is selected by type.
 */
export function validateEnvelope(value: unknown, path: string, out: SchemaViolation[]): void {
  const source = checkObject(value, path, out, ["id", "schema_version", "sequence", "type", "occurred_at", "recorded_at", "organisation_id", "project_id", "actor", "correlation", "payload"], ["id", "schema_version", "sequence", "type", "occurred_at", "organisation_id", "project_id", "actor", "payload"]);
  if (source === null) return;
  if (source["id"] !== undefined) {
    validateIdentifier(source["id"], `${path}.id`, out);
  }
  if (source["schema_version"] !== undefined) {
    validateEnvelopeSchemaVersion(source["schema_version"], `${path}.schema_version`, out);
  }
  if (source["sequence"] !== undefined) {
    validateSequenceNumber(source["sequence"], `${path}.sequence`, out);
  }
  if (source["type"] !== undefined) {
    validateMessageType(source["type"], `${path}.type`, out);
  }
  if (source["occurred_at"] !== undefined) {
    validateTimestamp(source["occurred_at"], `${path}.occurred_at`, out);
  }
  if (source["recorded_at"] !== undefined) {
    validateTimestamp(source["recorded_at"], `${path}.recorded_at`, out);
  }
  if (source["organisation_id"] !== undefined) {
    validateIdentifier(source["organisation_id"], `${path}.organisation_id`, out);
  }
  if (source["project_id"] !== undefined) {
    validateIdentifier(source["project_id"], `${path}.project_id`, out);
  }
  if (source["actor"] !== undefined) {
    validateActor(source["actor"], `${path}.actor`, out);
  }
  if (source["correlation"] !== undefined) {
    validateCorrelation(source["correlation"], `${path}.correlation`, out);
  }
  if (source["payload"] !== undefined) {
    validateEnvelopePayload(source["payload"], `${path}.payload`, out);
  }
}

/**
 * Identifiers that link an event to the request, session and records it came from
 * (docs/EVENTS.md section 2). It carries identifiers only: never a request body, a header
 * or a credential (section 8).
 */
export function validateCorrelation(value: unknown, path: string, out: SchemaViolation[]): void {
  const source = checkObject(value, path, out, ["request_id", "causation_event_id", "browser_session_id", "agent_session_id", "review_id", "finding_id", "annotation_id", "artefact_id"], []);
  if (source === null) return;
  if (source["request_id"] !== undefined) {
    validateIdentifier(source["request_id"], `${path}.request_id`, out);
  }
  if (source["causation_event_id"] !== undefined) {
    validateIdentifier(source["causation_event_id"], `${path}.causation_event_id`, out);
  }
  if (source["browser_session_id"] !== undefined) {
    validateIdentifier(source["browser_session_id"], `${path}.browser_session_id`, out);
  }
  if (source["agent_session_id"] !== undefined) {
    validateIdentifier(source["agent_session_id"], `${path}.agent_session_id`, out);
  }
  if (source["review_id"] !== undefined) {
    validateIdentifier(source["review_id"], `${path}.review_id`, out);
  }
  if (source["finding_id"] !== undefined) {
    validateIdentifier(source["finding_id"], `${path}.finding_id`, out);
  }
  if (source["annotation_id"] !== undefined) {
    validateIdentifier(source["annotation_id"], `${path}.annotation_id`, out);
  }
  if (source["artefact_id"] !== undefined) {
    validateIdentifier(source["artefact_id"], `${path}.artefact_id`, out);
  }
}
